1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"os"
7		"os/exec"
8		"strings"
9		"testing"
10	)
11	
12	// These tests are command-line regression coverage for "aggregate" with
13	// --window-ms, --slide-ms and --partitions given at the same time. They drive
14	// the real main() entry point in a child process (the recompiled test binary)
15	// and feed line-delimited JSON on standard input, so flag parsing, standard
16	// output/error separation and the process exit code are all exercised
17	// end-to-end; the existing package tests cover the library behavior directly.
18	
19	// aggregateCommand builds a child process that enters main() with
20	// ["aggregate", args...] and feeds input to its standard input. The child is
21	// the running test binary relaunched with TestHelperProcess, so no separate
22	// build step is needed.
23	func aggregateCommand(t *testing.T, input string, args ...string) *exec.Cmd {
24		t.Helper()
25		exe, err := os.Executable()
26		if err != nil {
27			t.Fatalf("locate test binary: %v", err)
28		}
29		cmdArgs := append([]string{"-test.run=^TestHelperProcess$", "--", "aggregate"}, args...)
30		cmd := exec.Command(exe, cmdArgs...)
31		cmd.Stdin = strings.NewReader(input)
32		cmd.Env = append(os.Environ(), "GO_WANT_HELPER_PROCESS=1")
33		return cmd
34	}
35	
36	// TestHelperProcess is the child-process entry point: it rewrites os.Args to
37	// the form main() expects ([binary, aggregate, flags...]) and hands control to
38	// main(), whose os.Exit calls become the child's real exit code.
39	func TestHelperProcess(t *testing.T) {
40		if os.Getenv("GO_WANT_HELPER_PROCESS") != "1" {
41			return
42		}
43		for i, a := range os.Args {
44			if a == "--" {
45				os.Args = append([]string{os.Args[0]}, os.Args[i+1:]...)
46				break
47			}
48		}
49		main()
50	}
51	
52	// windowLine is the exact on-the-wire aggregate result record: the existing
53	// key, start, end, count and sum fields and nothing else.
54	type windowLine struct {
55		Key   string `json:"key"`
56		Start int64  `json:"start"`
57		End   int64  `json:"end"`
58		Count int64  `json:"count"`
59		Sum   int64  `json:"sum"`
60	}
61	
62	// assertWindowLines verifies that stdout is one complete JSON object per
63	// physical line, in order, with exactly the existing fields (no partition
64	// field), and nothing trailing after the last newline.
65	func assertWindowLines(t *testing.T, stdout string, want []windowLine) {
66		t.Helper()
67		physicalLines := strings.Split(strings.TrimSuffix(stdout, "\n"), "\n")
68		if len(physicalLines) != len(want) {
69			t.Fatalf("stdout has %d result line(s), want %d:\n%s", len(physicalLines), len(want), stdout)
70		}
71		for i, text := range physicalLines {
72			var got windowLine
73			if err := json.Unmarshal([]byte(text), &got); err != nil {
74				t.Fatalf("stdout line %d is not a complete JSON object: %v (%q)", i+1, err, text)
75			}
76			if got != want[i] {
77				t.Fatalf("stdout line %d = %+v, want %+v", i+1, got, want[i])
78			}
79			var fields map[string]json.RawMessage
80			if err := json.Unmarshal([]byte(text), &fields); err != nil {
81				t.Fatalf("stdout line %d: %v", i+1, err)
82			}
83			if len(fields) != 5 {
84				t.Fatalf("stdout line %d carries %d fields, want exactly key,start,end,count,sum: %q", i+1, len(fields), text)
85			}
86			if _, ok := fields["partition"]; ok {
87				t.Fatalf("stdout line %d must not carry a partition field: %q", i+1, text)
88			}
89		}
90	}
91	
92	// TestAggregateCLIPartitionedSlidingWindow drives the documented usage with
93	// all three flags at once: window length 1000ms, slide interval 600ms and two
94	// partitions. The observed output proves every flag is actually used:
95	//   - --window-ms 1000 and --slide-ms 600 produce the overlapping windows
96	//     [0,1000) and [600,1600), and the time-1000 event stays out of [0,1000)
97	//     (that window reports count 1, sum 2, not count 2, sum 5);
98	//   - --partitions 2 accepts partition-bearing records and the idle record
99	//     (an idle record is fatal in single-watermark mode) and merges both
100	//     partitions into one count/sum per window ([600,1600) reports 2 and 5).
101	//
102	// Partition 0's watermark of 1600 alone must not close anything; once
103	// partition 1 reports 600 the effective watermark is 600 and still nothing
104	// closes; only partition 1's idle declaration raises the effective
105	// watermark to 1600 and emits both windows. A normal input ending right after
106	// the idle declaration exits 0 with empty standard error.
107	func TestAggregateCLIPartitionedSlidingWindow(t *testing.T) {
108		input := strings.Join([]string{
109			`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,  // line 1
110			`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`, // line 2
111			`{"type":"watermark","time":1600,"partition":0}`,                 // line 3: effective still unknown
112			`{"type":"watermark","time":600,"partition":1}`,                  // line 4: effective 600, nothing closes
113			`{"type":"idle","partition":1}`,                                  // line 5: effective 1600, both windows close
114		}, "\n") + "\n"
115	
116		cmd := aggregateCommand(t, input, "--window-ms", "1000", "--slide-ms", "600", "--partitions", "2")
117		var stdout, stderr bytes.Buffer
118		cmd.Stdout = &stdout
119		cmd.Stderr = &stderr
120		if err := cmd.Run(); err != nil {
121			t.Fatalf("aggregate failed: %v\nstderr: %s", err, stderr.String())
122		}
123		if code := cmd.ProcessState.ExitCode(); code != 0 {
124			t.Fatalf("exit code = %d, want 0", code)
125		}
126		if stderr.Len() != 0 {
127			t.Fatalf("stderr = %q, want empty", stderr.String())
128		}
129	
130		assertWindowLines(t, stdout.String(), []windowLine{
131			{Key: "k", Start: 0, End: 1000, Count: 1, Sum: 2},
132			{Key: "k", Start: 600, End: 1600, Count: 2, Sum: 5},
133		})
134	}
135	
136	// TestAggregateCLIEventForIdlePartitionIsFatal guards the failure boundary:
137	// an event arriving while its partition is idle is fatal with exit code 1,
138	// naming the idle partition and the event's physical input line (blank lines
139	// still count), even when the event time is below the current effective
140	// watermark -- it must not be downgraded to an ordinary late-event notice and
141	// a successful exit. The two fully written results stay on standard output,
142	// no later watermark produces anything, and the explanation stays on
143	// standard error only.
144	func TestAggregateCLIEventForIdlePartitionIsFatal(t *testing.T) {
145		input := strings.Join([]string{
146			`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,  // line 1
147			`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`, // line 2
148			`{"type":"event","key":"k","time":5000,"value":7,"partition":0}`, // line 3: later windows left open
149			`{"type":"watermark","time":1600,"partition":0}`,                 // line 4: effective still unknown
150			`{"type":"watermark","time":600,"partition":1}`,                  // line 5: effective 600, nothing closes
151			`{"type":"idle","partition":1}`,                                  // line 6: effective 1600, two results
152			``,                                                               // line 7: blank, still counted
153			`{"type":"event","key":"k","time":500,"value":1,"partition":1}`,  // line 8: idle p1 AND below wm 1600
154			`{"type":"watermark","time":5800,"partition":0}`,                 // line 9: must never be read
155		}, "\n") + "\n"
156	
157		cmd := aggregateCommand(t, input, "--window-ms", "1000", "--slide-ms", "600", "--partitions", "2")
158		var stdout, stderr bytes.Buffer
159		cmd.Stdout = &stdout
160		cmd.Stderr = &stderr
161		err := cmd.Run()
162		if err == nil {
163			t.Fatal("aggregate succeeded, want exit code 1 for an event on an idle partition")
164		}
165		if code := cmd.ProcessState.ExitCode(); code != 1 {
166			t.Fatalf("exit code = %d, want 1", code)
167		}
168	
169		errText := stderr.String()
170		for _, want := range []string{"line 8", "idle partition 1"} {
171			if !strings.Contains(errText, want) {
172				t.Fatalf("stderr = %q, want it to mention %q", errText, want)
173			}
174		}
175		if strings.Contains(errText, "late event") {
176			t.Fatalf("idle-partition event must not be reported as an ordinary late event: stderr = %q", errText)
177		}
178		if strings.Contains(stdout.String(), "idle") || strings.Contains(stdout.String(), "aggregate:") {
179			t.Fatalf("error explanation must not appear on stdout: %q", stdout.String())
180		}
181	
182		// Exactly the two results completed before the error; the time-5000 event
183		// opened later windows that line 9's watermark would close, so any extra
184		// line would prove processing continued after the fatal record.
185		assertWindowLines(t, stdout.String(), []windowLine{
186			{Key: "k", Start: 0, End: 1000, Count: 1, Sum: 2},
187			{Key: "k", Start: 600, End: 1600, Count: 2, Sum: 5},
188		})
