package edgefleet

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
	"testing"
)

func ProbeZBehavior(t *testing.T) {
	// 1. newline short escape vs \u000a merge; backslash+n distinct; slash variants
	input := strings.Join([]string{
		`{"type":"event","key":"a\nb","time":100,"value":2}`,
		"{\"type\":\"event\",\"key\":\"a\\u000ab\",\"time\":200,\"value\":3}",
		`{"type":"event","key":"a\\nb","time":300,"value":7}`, // literal backslash + n: distinct key
		`{"type":"event","key":"p/q","time":100,"value":1}`,
		`{"type":"event","key":"p\/q","time":200,"value":4}`,
		`{"type":"event","key":"p/q","time":300,"value":9}`,
		`{"type":"event","key":"tab\tx","time":100,"value":1}`,
		"{\"type\":\"event\",\"key\":\"tab\\u0009x\",\"time\":200,\"value\":10}",
		`{"type":"event","key":"cr\rx","time":100,"value":1}`,
		"{\"type\":\"event\",\"key\":\"cr\\u000dx\",\"time\":200,\"value\":100}",
		`{"type":"event","key":"q\"x","time":100,"value":1}`,
		"{\"type\":\"event\",\"key\":\"q\\u0022x\",\"time\":200,\"value\":1000}",
		`{"type":"event","key":"b\\x","time":100,"value":1}`,
		"{\"type\":\"event\",\"key\":\"b\\u005cx\",\"time\":200,\"value\":10000}",
		"{\"type\":\"event\",\"key\":\"nul\\u0000x\",\"time\":100,\"value\":5}",
		`{"type":"watermark","time":1000}`,
	}, "\n") + "\n"
	var out bytes.Buffer
	err := RunAggregate(strings.NewReader(input), 1000, &out, &out)
	fmt.Printf("=== case1 err=%v\n%s", err, out.String())
	for _, ln := range strings.Split(strings.TrimSuffix(out.String(), "\n"), "\n") {
		var r AggregateResult
		if e := json.Unmarshal([]byte(ln), &r); e != nil {
			fmt.Println("BAD JSON LINE:", e, ln)
			continue
		}
		fmt.Printf("key=%q count=%d sum=%d\n", r.Key, r.Count, r.Sum)
	}

	// 2. raw control char inside string
	raw := "{\"type\":\"event\",\"key\":\"a\tb\",\"time\":1,\"value\":1}\n" // literal tab
	var out2 bytes.Buffer
	err = RunAggregate(strings.NewReader(raw), 1000, &out2, &out2)
	fmt.Printf("=== raw tab err=%T %v\n", err, err)

	// 3. unsupported escape \x
	bad := `{"type":"event","key":"a\xb","time":1,"value":1}` + "\n"
	var out3 bytes.Buffer
	err = RunAggregate(strings.NewReader(bad), 1000, &out3, &out3)
	fmt.Printf("=== bad escape err=%T %v\n", err, err)

	// 4. trailing specials + consecutive backslashes round trip
	input4 := strings.Join([]string{
		`{"type":"event","key":"a\\\\","time":1,"value":1}`,  // ends with two backslashes
		`{"type":"event","key":"b\"","time":1,"value":1}`,   // ends with quote
		`{"type":"event","key":"c\n","time":1,"value":1}`,   // ends with newline
		"{\"type\":\"event\",\"key\":\"d\\u0000\",\"time\":1,\"value\":1}", // ends NUL
		`{"type":"event","key":"e\r","time":1,"value":1}`,   // ends CR
		`{"type":"watermark","time":1000}`,
	}, "\n") + "\n"
	var out4 bytes.Buffer
	err = RunAggregate(strings.NewReader(input4), 1000, &out4, &out4)
	fmt.Printf("=== case4 err=%v\n", err)
	fmt.Printf("raw out: %q\n", out4.String())
	if n := strings.Count(out4.String(), "\n"); n != 5 {
		fmt.Println("PHYSICAL LINE COUNT WRONG:", n)
	}
	for _, ln := range strings.Split(strings.TrimSuffix(out4.String(), "\n"), "\n") {
		var r AggregateResult
		if e := json.Unmarshal([]byte(ln), &r); e != nil {
			fmt.Println("BAD JSON:", e, ln)
		} else {
			fmt.Printf("key=%q\n", r.Key)
		}
	}
}

