package edgefleet

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
	"testing"
)

func TestZProbe2(t *testing.T) {
	// raw CR and raw NUL inside the key string
	for name, raw := range map[string]string{
		"raw-cr":  "{\"type\":\"event\",\"key\":\"a\rb\",\"time\":1,\"value\":1}\n",
		"raw-nul": "{\"type\":\"event\",\"key\":\"a\x00b\",\"time\":1,\"value\":1}\n",
		"raw-lf-first-half": "{\"type\":\"event\",\"key\":\"a\nb\",\"time\":1,\"value\":1}\n",
	} {
		var out bytes.Buffer
		err := RunAggregate(strings.NewReader(raw), 1000, &out, &out)
		fmt.Printf("%s: err=%T %v\n", name, err, err)
	}

