		{"raw nul in string", "{\"type\":\"event\",\"key\":\"a\x00b\",\"time\":1,\"value\":1}", 1},
		{"raw newline in string splits the record", "{\"type\":\"event\",\"key\":\"a\nb\",\"time\":1,\"value\":1}", 1},
		{"unsupported escape x", `{"type":"event","key":"a\xb","time":1,"value":1}`, 1},
