		t.Run(tc.name, func(t *testing.T) {
			input := tc.record + "\n"
			stdout, stderr, err := runAggregate(t, input, 1000)
			inputErr, ok := err.(*InputError)
			if !ok {
				t.Fatalf("want *InputError, got %T: %v", err, err)
			}
			if inputErr.Line != tc.wantLine {
